import { useState } from 'react';
import './ControlPanel.css';

const MONTHS = ['01','02','03','04','05','06','07','08','09','10','11','12'];

const HALF_MAP = {
  H1: ['01','02','03','04','05','06'],
  H2: ['07','08','09','10','11','12'],
};
const QUARTER_MAP = {
  Q1: ['01','02','03'],
  Q2: ['04','05','06'],
  Q3: ['07','08','09'],
  Q4: ['10','11','12'],
};

export default function ControlPanel({ years, stores, filters, onFilterChange }) {
  const [collapsed, setCollapsed] = useState(false);
  const [periodType, setPeriodType] = useState('month'); // 'annual'|'half'|'quarter'|'month'
  const [halfSel, setHalfSel] = useState(null);
  const [quarterSel, setQuarterSel] = useState(null);

  const setMonths = (months) => onFilterChange({ ...filters, months });

  const handlePeriodType = (type) => {
    setPeriodType(type);
    setHalfSel(null);
    setQuarterSel(null);
    if (type === 'annual') setMonths([]);
    else setMonths([]);
  };

  const handleHalf = (h) => {
    const next = halfSel === h ? null : h;
    setHalfSel(next);
    setMonths(next ? HALF_MAP[next] : []);
  };

  const handleQuarter = (q) => {
    const next = quarterSel === q ? null : q;
    setQuarterSel(next);
    setMonths(next ? QUARTER_MAP[next] : []);
  };

  const handleMonth = (m) => {
    const cur = filters.months || [];
    const next = cur.includes(m) ? cur.filter((x) => x !== m) : [...cur, m];
    onFilterChange({ ...filters, months: next });
  };

  const handleStore = (s) => {
    const cur = filters.stores || [];
    const next = cur.includes(s) ? cur.filter((x) => x !== s) : [...cur, s];
    onFilterChange({ ...filters, stores: next });
  };

  const handleDayType = (v) => onFilterChange({ ...filters, dayType: v });
  const handleMealTime = (v) => onFilterChange({ ...filters, mealTime: v });

  if (collapsed) {
    return (
      <div className="cp-collapsed">
        <button className="cp-toggle-btn" onClick={() => setCollapsed(false)} title="필터 열기">
          ▶
        </button>
      </div>
    );
  }

  return (
    <div className="cp-panel">
      {/* 헤더 */}
      <div className="cp-header">
        <span className="cp-title">🎛 필터</span>
        <button className="cp-toggle-btn" onClick={() => setCollapsed(true)} title="필터 닫기">◀</button>
      </div>

      {/* 연도 */}
      <div className="cp-section">
        <div className="cp-label">연도</div>
        <div className="cp-chips">
          {years.map((y) => (
            <button
              key={y}
              className={`cp-chip ${filters.year === y ? 'active' : ''}`}
              onClick={() => onFilterChange({ ...filters, year: y })}
            >
              {y}
            </button>
          ))}
        </div>
      </div>

      {/* 기간 단위 */}
      <div className="cp-section">
        <div className="cp-label">기간 단위</div>
        <div className="cp-chips">
          {[['annual','연간'],['half','반기'],['quarter','분기'],['month','월별']].map(([v, label]) => (
            <button
              key={v}
              className={`cp-chip ${periodType === v ? 'active' : ''}`}
              onClick={() => handlePeriodType(v)}
            >
              {label}
            </button>
          ))}
        </div>

        {/* 반기 선택 */}
        {periodType === 'half' && (
          <div className="cp-chips cp-sub-chips">
            {[['H1','상반기'],['H2','하반기']].map(([v, label]) => (
              <button
                key={v}
                className={`cp-chip ${halfSel === v ? 'active' : ''}`}
                onClick={() => handleHalf(v)}
              >
                {label}
              </button>
            ))}
          </div>
        )}

        {/* 분기 선택 */}
        {periodType === 'quarter' && (
          <div className="cp-chips cp-sub-chips">
            {['Q1','Q2','Q3','Q4'].map((q) => (
              <button
                key={q}
                className={`cp-chip ${quarterSel === q ? 'active' : ''}`}
                onClick={() => handleQuarter(q)}
              >
                {q}
              </button>
            ))}
          </div>
        )}

        {/* 월별 선택 */}
        {periodType === 'month' && (
          <div className="cp-chips cp-sub-chips">
            <button
              className={`cp-chip ${!filters.months?.length ? 'active' : ''}`}
              onClick={() => setMonths([])}
            >
              전체
            </button>
            {MONTHS.map((m) => (
              <button
                key={m}
                className={`cp-chip ${filters.months?.includes(m) ? 'active' : ''}`}
                onClick={() => handleMonth(m)}
              >
                {parseInt(m)}월
              </button>
            ))}
          </div>
        )}
      </div>

      {/* 매장 */}
      <div className="cp-section">
        <div className="cp-label">매장</div>
        <div className="cp-chips">
          <button
            className={`cp-chip ${!filters.stores?.length ? 'active' : ''}`}
            onClick={() => onFilterChange({ ...filters, stores: [] })}
          >
            전체
          </button>
          {stores.map((s) => (
            <button
              key={s}
              className={`cp-chip ${filters.stores?.includes(s) ? 'active' : ''}`}
              onClick={() => handleStore(s)}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      {/* 주중/주말 */}
      <div className="cp-section">
        <div className="cp-label">요일 구분</div>
        <div className="cp-chips">
          {[['all','전체'],['weekday','주중'],['weekend','주말']].map(([v, label]) => (
            <button
              key={v}
              className={`cp-chip ${(filters.dayType || 'all') === v ? 'active' : ''}`}
              onClick={() => handleDayType(v)}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      {/* 점심/저녁 */}
      <div className="cp-section">
        <div className="cp-label">시간대</div>
        <div className="cp-chips">
          {[['all','전체'],['lunch','점심'],['dinner','저녁']].map(([v, label]) => (
            <button
              key={v}
              className={`cp-chip ${(filters.mealTime || 'all') === v ? 'active' : ''}`}
              onClick={() => handleMealTime(v)}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      {/* 초기화 */}
      <div className="cp-section">
        <button
          className="cp-reset-btn"
          onClick={() => {
            setPeriodType('month');
            setHalfSel(null);
            setQuarterSel(null);
            onFilterChange({
              year: years[years.length - 1] || '',
              months: [],
              stores: [],
              dayType: 'all',
              mealTime: 'all',
            });
          }}
        >
          ↺ 필터 초기화
        </button>
      </div>
    </div>
  );
}
