import { useState, useMemo, useEffect } from 'react';
import {
  BarChart, Bar, LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell,
} from 'recharts';
import FileUpload from './FileUpload';
import OpInfoUpload from './OpInfoUpload';
import ControlPanel from './ControlPanel';
import DataManager from './DataManager';
import PMix from './PMix';
import DailyTrend from './DailyTrend';
import YoY from './YoY';
import DaypartCompare from './DaypartCompare';
import MenuEngineering from './MenuEngineering';
import AbcAnalysis from './AbcAnalysis';
import StoreDetail from './StoreDetail';
import CumulativeTrend from './CumulativeTrend';
import WeeklyReport from './WeeklyReport';
import BudgetActual from './BudgetActual';
import ExportReport from './ExportReport';
import AnomalyAlert from './AnomalyAlert';
import {
  aggregateByStore, aggregateByMonth, getYears, getStores,
  formatKRW, formatShort, sortByStore, calcGrowthRate, STORE_ORDER,
} from '../utils/calcMetrics';
import { saveAllData, loadAllData, clearAllData, saveOpData, loadOpData, clearOpData } from '../utils/storage';
import './Dashboard.css';

// Firebase import 제거 완료 — storage는 localStorage 기반

// 매장별 고정 색상
const STORE_COLORS = ['#0d2258','#1d4ed8','#7c3aed','#0f766e','#dc2626','#d97706','#059669','#be185d'];
function storeColor(store) {
  const idx = STORE_ORDER.indexOf(store);
  return STORE_COLORS[idx !== -1 ? idx : 0];
}

const ROLE_KEY = 'brand_role_v1';

function directLogout(onLogout) {
  sessionStorage.removeItem(ROLE_KEY);
  if (typeof onLogout === 'function') onLogout();
  // 어떤 경우에도 페이지 이동으로 보장
  window.location.replace(window.location.href);
}

export default function Dashboard({ isAdmin = false, onLogout }) {
  const [allData, setAllData] = useState([]);
  const [opData, setOpData] = useState([]);
  const [filters, setFilters] = useState({ year: '', months: [], stores: [], dayType: 'all', mealTime: 'all' });
  const [activeTab, setActiveTab] = useState('overview');
  const [dbLoading, setDbLoading] = useState(true);

  // 앱 시작 시 저장된 데이터 불러오기
  useEffect(() => {
    Promise.all([loadAllData(), loadOpData()]).then(([saved, savedOp]) => {
      if (saved.length > 0) {
        setAllData(saved);
        const years = [...new Set(saved.map((d) => d.year))].sort();
        setFilters((f) => ({ ...f, year: years[years.length - 1] }));
      }
      if (savedOp.length > 0) setOpData(savedOp);
      setDbLoading(false);
    }).catch(() => {
      setDbLoading(false);
    });
  }, []);

  const handleDataLoaded = (newResults) => {
    setAllData((prev) => {
      const map = {};
      [...prev, ...newResults].forEach((d) => { map[d.key] = d; });
      const merged = Object.values(map);
      saveAllData(merged);
      return merged;
    });
    if (newResults.length > 0 && !filters.year) {
      const years = [...new Set(newResults.map((d) => d.year))].sort();
      setFilters((f) => ({ ...f, year: years[years.length - 1] }));
    }
  };

  const handleOpDataLoaded = (newResults) => {
    setOpData((prev) => {
      const map = {};
      [...prev, ...newResults].forEach((d) => { map[d.key] = d; });
      const merged = Object.values(map);
      saveOpData(merged);
      return merged;
    });
  };

  const handleClearData = async () => {
    if (window.confirm('저장된 데이터를 모두 삭제할까요? (이지포스 + 영업정보)')) {
      await Promise.all([clearAllData(), clearOpData()]);
      setAllData([]);
      setOpData([]);
      setFilters({ year: '', months: [], stores: [] });
    }
  };

  // ── 데이터 내보내기 (JSON 파일 다운로드) ──────────────────
  const handleExport = () => {
    const payload = { version: 1, allData, opData, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `brand-analytics-backup-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // ── 데이터 가져오기 (JSON 파일 업로드) ───────────────────
  const handleImport = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      try {
        const { allData: importedSales, opData: importedOp } = JSON.parse(ev.target.result);
        if (importedSales?.length > 0) {
          setAllData((prev) => {
            const map = {};
            [...prev, ...importedSales].forEach((d) => { map[d.key] = d; });
            const merged = Object.values(map);
            saveAllData(merged);
            return merged;
          });
        }
        if (importedOp?.length > 0) {
          setOpData((prev) => {
            const map = {};
            [...prev, ...importedOp].forEach((d) => { map[d.key] = d; });
            const merged = Object.values(map);
            saveOpData(merged);
            return merged;
          });
        }
        alert(`✅ 가져오기 완료!\n이지포스: ${importedSales?.length || 0}건\n영업정보: ${importedOp?.length || 0}건`);
      } catch {
        alert('❌ 파일을 읽을 수 없습니다. 올바른 백업 파일인지 확인하세요.');
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const years = useMemo(() => getYears(allData), [allData]);
  const stores = useMemo(() => getStores(allData), [allData]);
  const storeData = useMemo(() => aggregateByStore(allData, filters), [allData, filters]);
  const monthlyData = useMemo(() => aggregateByMonth(allData, filters), [allData, filters]);

  // 월별 매장 비교 (멀티 라인)
  const monthlyByStore = useMemo(() => {
    const visibleStores = filters.stores?.length ? filters.stores : stores;
    const months = [...new Set(
      allData
        .filter((d) => !filters.year || d.year === filters.year)
        .filter((d) => !filters.months?.length || filters.months.includes(d.month))
        .map((d) => `${d.year}-${d.month}`)
    )].sort();
    return months.map((ym) => {
      const [year, month] = ym.split('-');
      const entry = { yearMonth: ym };
      visibleStores.forEach((store) => {
        const item = allData.find((d) => d.year === year && d.month === month && d.store === store);
        entry[store] = item ? item.totalSales : 0;
      });
      return entry;
    });
  }, [allData, filters, stores]);

  // 전년 동기 대비 성장률 (매장별)
  const storeGrowth = useMemo(() => {
    if (!filters.year) return {};
    const prevYear = String(Number(filters.year) - 1);
    const prevFilters = { ...filters, year: prevYear };
    const prev = aggregateByStore(allData, prevFilters);
    const prevMap = Object.fromEntries(prev.map((s) => [s.store, s.totalSales]));
    const growth = {};
    storeData.forEach((s) => {
      growth[s.store] = calcGrowthRate(s.totalSales, prevMap[s.store] || 0);
    });
    return growth;
  }, [allData, filters, storeData]);

  // 총 매출 (이지포스 기반)
  const totalSales = storeData.reduce((s, d) => s + d.totalSales, 0);

  // 영업정보 기반 KPI (필터 적용 — dayType/mealTime 포함)
  const filteredOpData = useMemo(() => {
    const { dayType = 'all', mealTime = 'all' } = filters;
    return opData
      .filter((d) => {
        const yearMatch = !filters.year || d.year === filters.year;
        const monthMatch = !filters.months?.length || filters.months.includes(d.month);
        const storeMatch = !filters.stores?.length || filters.stores.includes(d.store);
        return yearMatch && monthMatch && storeMatch;
      })
      .map((d) => ({
        ...d,
        dailyOp: d.dailyOp
          // ① 요일 필터
          .filter((day) => {
            if (dayType === 'all') return true;
            const isWknd = day.isWeekend !== undefined
              ? day.isWeekend
              : (() => { const dow = new Date(day.date).getDay(); return dow === 0 || dow === 6; })();
            return dayType === 'weekend' ? isWknd : !isWknd;
          })
          // ② 시간대 필터: 점심/저녁 시 해당 값으로 대체
          .map((day) => {
            if (mealTime === 'lunch') {
              return {
                ...day,
                sales: day.lunchSales ?? 0,
                guests: day.lunchGuests ?? 0,
                txCount: day.lunchTxCount ?? 0,
              };
            }
            if (mealTime === 'dinner') {
              return {
                ...day,
                sales: day.dinnerSales ?? 0,
                guests: day.dinnerGuests ?? 0,
                txCount: day.dinnerTxCount ?? 0,
              };
            }
            return day;
          }),
      }));
  }, [opData, filters]);

  const { totalGuests, totalTx, avgPerTx, avgPerGuest, txGuestRatio } = useMemo(() => {
    let guests = 0, tx = 0, opSales = 0;
    filteredOpData.forEach((d) => {
      d.dailyOp.forEach((day) => {
        guests += day.guests;
        tx += day.txCount;
        opSales += day.sales;
      });
    });
    const ratio = guests > 0 ? tx / guests : 0;
    return {
      totalGuests: guests,
      totalTx: tx,
      avgPerTx: tx > 0 ? opSales / tx : 0,
      avgPerGuest: guests > 0 ? opSales / guests : 0,
      txGuestRatio: ratio,
    };
  }, [filteredOpData]);

  const hasOpData = opData.length > 0;
  const storeSalesChart = sortByStore(storeData);

  if (dbLoading) {
    return (
      <div className="dashboard-empty">
        <div className="empty-title">⏳ 데이터 불러오는 중...</div>
      </div>
    );
  }

  if (allData.length === 0) {
    return (
      <div className="dashboard-empty">
        <div className="empty-title">📊 브랜드 매출 분석 대시보드</div>
        {/* 현재 역할 배지 — 로그인 상태 확인용 */}
        <div style={{ display: 'inline-block', padding: '3px 12px', borderRadius: 20, fontSize: 12, fontWeight: 700,
          background: isAdmin ? '#0d2258' : '#e5e7eb', color: isAdmin ? '#fff' : '#6b7280', marginBottom: 4 }}>
          {isAdmin ? '🔑 관리자 (Admin)' : '👁 열람 (Viewer)'}
        </div>
        {isAdmin ? (
          <>
            <div className="empty-sub">이지포스 엑셀 파일을 업로드하거나 백업 파일을 가져오세요</div>
            <div style={{ display: 'flex', gap: 12, justifyContent: 'center', marginBottom: 24 }}>
              <label className="btn-export" style={{ cursor: 'pointer', padding: '10px 24px', fontSize: 14 }}>
                📥 백업 파일 가져오기 (.json)
                <input type="file" accept=".json" style={{ display: 'none' }} onChange={handleImport} />
              </label>
            </div>
            <FileUpload onDataLoaded={handleDataLoaded} existingCount={0} />
          </>
        ) : (
          <div className="empty-sub">관리자 계정으로 로그인하면 데이터를 업로드할 수 있습니다.</div>
        )}
        <button
          type="button"
          onClick={() => directLogout(onLogout)}
          style={{ marginTop: 24, padding: '8px 20px', background: '#f3f4f6', border: '1px solid #d1d5db', borderRadius: 6, cursor: 'pointer', color: '#374151' }}
        >
          로그아웃
        </button>
      </div>
    );
  }

  return (
    <div className="dashboard">
      <div className="dash-header">
        <div className="dash-title">📊 브랜드 매출 분석 대시보드</div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {isAdmin && (
            <>
              <button className="btn-export" onClick={handleExport}>📤 내보내기</button>
              <label className="btn-export" style={{ cursor: 'pointer' }}>
                📥 가져오기
                <input type="file" accept=".json" style={{ display: 'none' }} onChange={handleImport} />
              </label>
              <button className="btn-clear" onClick={handleClearData}>데이터 초기화</button>
            </>
          )}
          <button
            type="button"
            className="btn-clear"
            onClick={() => directLogout(onLogout)}
            style={{ background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db' }}
          >
            로그아웃
          </button>
        </div>
      </div>

      <div className="dash-body">
        <ControlPanel years={years} stores={stores} filters={filters} onFilterChange={setFilters} />

        <div className="dash-main">
        {/* 이상 감지 알림 */}
        {allData.length > 0 && <AnomalyAlert allData={allData} />}

        <div className="tab-bar">
        {[
          ['overview', '매장별 비교'],
          ['monthly', '월별 추이'],
          ['opinfo', `영업정보${hasOpData ? ` (${opData.length}건)` : ' ⬆'}`],
          ['pmix', 'P-Mix'],
          ['daily', '일별 추이'],
          ['yoy', '전년 대비'],
          ['daypart', '점심/저녁'],
          ['menueng', '메뉴 엔지니어링'],
          ['abc', 'ABC분석'],
          ['storedetail', '매장 상세'],
          ['cumulative', '누적·추세'],
          ['weekly', '주간 리포트'],
          ['budget', '목표 실적'],
          ['export', '리포트 내보내기'],
          ['datamanager', `📁 데이터 관리 (${allData.length}건)`],
          ...(isAdmin ? [['upload', '파일 추가']] : []),
        ].map(([key, label]) => (
          <button key={key} className={`tab-btn ${activeTab === key ? 'active' : ''}`} onClick={() => setActiveTab(key)}>
            {label}
          </button>
        ))}
      </div>

      {activeTab === 'overview' && (
        <div className="tab-content">
          {/* KPI 요약 카드 */}
          <div className="kpi-row">
            <KpiCard label="총 매출" value={formatShort(totalSales)} sub={`${formatKRW(totalSales)}원`} color="#0d2258" />
            {hasOpData ? (
              <>
                <KpiCard label="총 고객수" value={formatKRW(totalGuests)} sub="명" color="#1d4ed8" />
                <KpiCard label="영수단가" value={formatKRW(Math.round(avgPerTx))} sub="원/건" color="#7c3aed" />
                <KpiCard label="객단가" value={formatKRW(Math.round(avgPerGuest))} sub="원/명" color="#0f766e" />
                <KpiCard label="영수/고객비율" value={txGuestRatio.toFixed(2)} sub="건/명" color="#dc2626" />
              </>
            ) : (
              <>
                <KpiCard label="매장 수" value={stores.length} sub="개 매장" color="#1d4ed8" />
                <KpiCard label="이지포스 데이터" value={allData.length} sub="개 (매장×월)" color="#7c3aed" />
                <KpiCard label="영업정보" value="미업로드" sub="영업정보 탭에서 업로드" color="#9ca3af" badge />
              </>
            )}
          </div>
          {/* ① 매장별 총 매출 + 매출 구성비 */}
          <div className="chart-grid-2">
            <div className="chart-card">
              <div className="chart-title">매장별 총 매출</div>
              <ResponsiveContainer width="100%" height={280}>
                <BarChart data={storeSalesChart} margin={{ top: 10, right: 16, left: 10, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis dataKey="store" tick={{ fontSize: 12 }} />
                  <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '매출']} />
                  <Bar dataKey="totalSales" radius={[4,4,0,0]} name="총 매출">
                    {storeSalesChart.map((s) => (
                      <Cell key={s.store} fill={storeColor(s.store)} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
            <div className="chart-card">
              <div className="chart-title">매출 구성비</div>
              <ResponsiveContainer width="100%" height={280}>
                <PieChart>
                  <Pie
                    data={storeSalesChart}
                    dataKey="totalSales"
                    nameKey="store"
                    cx="50%" cy="50%"
                    outerRadius={90} innerRadius={45}
                    paddingAngle={2}
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(1)}%`}
                    labelLine={false}
                  >
                    {storeSalesChart.map((s) => (
                      <Cell key={s.store} fill={storeColor(s.store)} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '매출']} />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* ② 월별 매장 비교 (멀티 라인) */}
          {monthlyByStore.length > 1 && (
            <div className="chart-card">
              <div className="chart-title">월별 매장별 매출 비교</div>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={monthlyByStore} margin={{ top: 10, right: 20, left: 10, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                  <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
                  <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v, name) => [`${formatKRW(v)}원`, name]} />
                  <Legend />
                  {(filters.stores?.length ? filters.stores : stores).map((store) => (
                    <Line
                      key={store} type="monotone" dataKey={store}
                      stroke={storeColor(store)} strokeWidth={2}
                      dot={{ r: 3 }} activeDot={{ r: 5 }}
                    />
                  ))}
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* ③ 영업정보 있을 때: 고객수 + 영수단가 비교 */}
          {hasOpData && (
            <div className="chart-grid-2">
              <div className="chart-card">
                <div className="chart-title">매장별 총 고객수</div>
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={storeOpChart(storeSalesChart, filteredOpData)} margin={{ top: 10, right: 16, left: 10, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis dataKey="store" tick={{ fontSize: 11 }} />
                    <YAxis tickFormatter={(v) => v.toLocaleString()} tick={{ fontSize: 11 }} />
                    <Tooltip formatter={(v) => [`${v.toLocaleString()}명`, '고객수']} />
                    <Bar dataKey="guests" radius={[4,4,0,0]} name="고객수">
                      {storeOpChart(storeSalesChart, filteredOpData).map((s) => (
                        <Cell key={s.store} fill={storeColor(s.store)} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <div className="chart-card">
                <div className="chart-title">매장별 영수단가</div>
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={storeOpChart(storeSalesChart, filteredOpData)} margin={{ top: 10, right: 16, left: 10, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                    <XAxis dataKey="store" tick={{ fontSize: 11 }} />
                    <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
                    <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '영수단가']} />
                    <Bar dataKey="avgPerTx" radius={[4,4,0,0]} name="영수단가">
                      {storeOpChart(storeSalesChart, filteredOpData).map((s) => (
                        <Cell key={s.store} fill={storeColor(s.store)} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </div>
          )}

          {/* ④ 매장별 상세 현황 테이블 (순위 + 전년 대비) */}
          <div className="chart-card">
            <div className="chart-title">매장별 상세 현황</div>
            <table className="data-table">
              <thead>
                <tr>
                  <th>순위</th><th>매장</th><th>총 매출</th><th>구성비</th><th>전년 대비</th>
                  {hasOpData && <><th>고객수</th><th>영수건수</th><th>영수단가</th><th>객단가</th></>}
                </tr>
              </thead>
              <tbody>
                {[...storeSalesChart].sort((a, b) => b.totalSales - a.totalSales).map((s, idx) => {
                  const op = filteredOpData.filter((d) => d.store === s.store);
                  const guests = op.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.guests, 0), 0);
                  const tx = op.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.txCount, 0), 0);
                  const opSales = op.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.sales, 0), 0);
                  const share = totalSales > 0 ? (s.totalSales / totalSales * 100).toFixed(1) : '0.0';
                  const growth = storeGrowth[s.store];
                  const rankEmoji = idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : `${idx + 1}`;
                  return (
                    <tr key={s.store}>
                      <td style={{ textAlign: 'center', fontWeight: 600 }}>{rankEmoji}</td>
                      <td className="td-store">
                        <span style={{ display: 'inline-block', width: 8, height: 8, borderRadius: '50%', background: storeColor(s.store), marginRight: 6 }} />
                        {s.store}
                      </td>
                      <td className="td-num">{formatKRW(s.totalSales)}원</td>
                      <td className="td-num">{share}%</td>
                      <td className="td-num" style={{ color: growth == null ? '#9ca3af' : growth >= 0 ? '#059669' : '#dc2626', fontWeight: 600 }}>
                        {growth == null ? '-' : `${growth >= 0 ? '+' : ''}${growth.toFixed(1)}%`}
                      </td>
                      {hasOpData && (
                        <>
                          <td className="td-num">{formatKRW(guests)}명</td>
                          <td className="td-num">{formatKRW(tx)}건</td>
                          <td className="td-num">{formatKRW(Math.round(tx > 0 ? opSales / tx : 0))}원</td>
                          <td className="td-num">{formatKRW(Math.round(guests > 0 ? opSales / guests : 0))}원</td>
                        </>
                      )}
                    </tr>
                  );
                })}
                <tr className="total-row">
                  <td></td><td>합계</td>
                  <td className="td-num">{formatKRW(totalSales)}원</td>
                  <td className="td-num">100%</td>
                  <td></td>
                  {hasOpData && (
                    <>
                      <td className="td-num">{formatKRW(totalGuests)}명</td>
                      <td className="td-num">{formatKRW(totalTx)}건</td>
                      <td className="td-num">{formatKRW(Math.round(avgPerTx))}원</td>
                      <td className="td-num">{formatKRW(Math.round(avgPerGuest))}원</td>
                    </>
                  )}
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'monthly' && (
        <div className="tab-content">
          <div className="chart-card">
            <div className="chart-title">월별 매출 추이</div>
            <ResponsiveContainer width="100%" height={320}>
              <LineChart data={monthlyData} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
                <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
                <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '매출']} />
                <Legend />
                <Line type="monotone" dataKey="totalSales" stroke="#0d2258" strokeWidth={2} dot={{ r: 4 }} name="총 매출" />
              </LineChart>
            </ResponsiveContainer>
          </div>
          {hasOpData && <MonthlyOpChart opData={opData} filters={filters} />}
          <div className="chart-card">
            <div className="chart-title">월별 상세 현황</div>
            <table className="data-table">
              <thead>
                <tr>
                  <th>연월</th><th>총 매출</th>
                  {hasOpData && <><th>고객수</th><th>영수단가</th></>}
                </tr>
              </thead>
              <tbody>
                {monthlyData.map((m) => {
                  const opMonth = opData.filter((d) => {
                    const yMatch = !filters.year || d.year === filters.year;
                    const sMatch = !filters.stores?.length || filters.stores.includes(d.store);
                    return d.year === m.year && d.month === m.month && sMatch && yMatch;
                  });
                  const guests = opMonth.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.guests, 0), 0);
                  const tx = opMonth.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.txCount, 0), 0);
                  return (
                    <tr key={m.yearMonth}>
                      <td>{m.yearMonth}</td>
                      <td className="td-num">{formatKRW(m.totalSales)}원</td>
                      {hasOpData && (
                        <>
                          <td className="td-num">{formatKRW(guests)}명</td>
                          <td className="td-num">{formatKRW(Math.round(tx > 0 ? m.totalSales / tx : 0))}원</td>
                        </>
                      )}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'opinfo' && (
        <div className="tab-content">
          {isAdmin && <OpInfoUpload onDataLoaded={handleOpDataLoaded} existingCount={opData.length} />}
          {hasOpData && <OpInfoSummary opData={filteredOpData} />}
          {!hasOpData && !isAdmin && (
            <div className="dashboard-empty" style={{ padding: 40 }}>
              <div className="empty-title">영업정보 데이터가 없습니다</div>
              <div className="empty-sub">관리자가 업로드한 후 확인하세요.</div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'pmix' && <PMix allData={allData} filters={filters} />}
      {activeTab === 'daily' && <DailyTrend allData={allData} filters={filters} opData={opData} />}
      {activeTab === 'yoy' && <YoY allData={allData} />}
      {activeTab === 'daypart' && (
        hasOpData
          ? <DaypartCompare opData={opData} filters={filters} />
          : <div className="tab-content"><div className="dashboard-empty" style={{ padding: 40 }}>
              <div className="empty-title">영업정보 데이터가 없습니다</div>
              <div className="empty-sub">영업정보 탭에서 파일을 업로드하면 점심/저녁 분석을 확인할 수 있습니다.</div>
            </div></div>
      )}
      {activeTab === 'menueng' && <MenuEngineering allData={allData} filters={filters} />}
      {activeTab === 'abc' && <AbcAnalysis allData={allData} filters={filters} />}
      {activeTab === 'storedetail' && <StoreDetail allData={allData} opData={opData} filters={filters} />}
      {activeTab === 'cumulative' && <CumulativeTrend allData={allData} filters={filters} />}
      {activeTab === 'weekly' && <WeeklyReport allData={allData} filters={filters} />}
      {activeTab === 'budget' && <BudgetActual allData={allData} filters={filters} />}
      {activeTab === 'export' && <ExportReport allData={allData} opData={opData} filters={filters} />}

      {activeTab === 'datamanager' && (
        <div className="tab-content">
          <DataManager
            allData={allData}
            opData={opData}
            isAdmin={isAdmin}
            onDataChanged={() => {
              Promise.all([
                import('../utils/storage').then(m => m.loadAllData()),
                import('../utils/storage').then(m => m.loadOpData()),
              ]).then(([sales, op]) => {
                setAllData(sales);
                setOpData(op);
              });
            }}
          />
        </div>
      )}

      {activeTab === 'upload' && (
        <div className="tab-content">
          <div className="chart-card">
            <div className="chart-title">이지포스 파일 추가 업로드 (.xlsx)</div>
            <FileUpload onDataLoaded={handleDataLoaded} existingCount={allData.length} />
          </div>
          <div className="chart-card" style={{ marginTop: 16 }}>
            <div className="chart-title">영업정보 업로드 (.xls)</div>
            <OpInfoUpload onDataLoaded={handleOpDataLoaded} existingCount={opData.length} />
          </div>
        </div>
      )}
        </div>{/* dash-main */}
      </div>{/* dash-body */}
    </div>
  );
}

// ─── 헬퍼: 매장별 영업정보 집계 ──────────────────────────
function storeOpChart(storeSalesChart, filteredOpData) {
  return storeSalesChart.map((s) => {
    const op = filteredOpData.filter((d) => d.store === s.store);
    const guests = op.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.guests, 0), 0);
    const tx = op.reduce((a, d) => a + d.dailyOp.reduce((b, day) => b + day.txCount, 0), 0);
    return {
      store: s.store,
      guests,
      txCount: tx,
      avgPerTx: tx > 0 ? s.totalSales / tx : 0,
      avgPerGuest: guests > 0 ? s.totalSales / guests : 0,
    };
  });
}

// ─── 월별 고객수 추이 차트 ────────────────────────────────
function MonthlyOpChart({ opData, filters }) {
  const data = useMemo(() => {
    const map = {};
    opData.forEach((d) => {
      if (filters.year && d.year !== filters.year) return;
      if (filters.stores?.length && !filters.stores.includes(d.store)) return;
      const key = `${d.year}-${d.month}`;
      if (!map[key]) map[key] = { yearMonth: key, guests: 0, txCount: 0 };
      d.dailyOp.forEach((day) => {
        map[key].guests += day.guests;
        map[key].txCount += day.txCount;
      });
    });
    return Object.values(map).sort((a, b) => a.yearMonth.localeCompare(b.yearMonth));
  }, [opData, filters]);

  return (
    <div className="chart-card">
      <div className="chart-title">월별 고객수 추이</div>
      <ResponsiveContainer width="100%" height={260}>
        <LineChart data={data} margin={{ top: 10, right: 20, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
          <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
          <YAxis tickFormatter={(v) => v.toLocaleString()} tick={{ fontSize: 11 }} />
          <Tooltip formatter={(v, name) => [
            name === 'guests' ? `${v.toLocaleString()}명` : `${v.toLocaleString()}건`,
            name === 'guests' ? '고객수' : '영수건수'
          ]} />
          <Legend formatter={(v) => v === 'guests' ? '고객수' : '영수건수'} />
          <Line type="monotone" dataKey="guests" stroke="#1d4ed8" strokeWidth={2} dot={{ r: 3 }} name="guests" />
          <Line type="monotone" dataKey="txCount" stroke="#7c3aed" strokeWidth={2} dot={{ r: 3 }} name="txCount" />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

// ─── 영업정보 탭 요약 ──────────────────────────────────────
function OpInfoSummary({ opData }) {
  const storeStats = useMemo(() => {
    const map = {};
    opData.forEach((d) => {
      if (!map[d.store]) map[d.store] = { store: d.store, sales: 0, guests: 0, txCount: 0 };
      d.dailyOp.forEach((day) => {
        map[d.store].sales += day.sales;
        map[d.store].guests += day.guests;
        map[d.store].txCount += day.txCount;
      });
    });
    return Object.values(map)
      .filter((s) => s.guests > 0 || s.txCount > 0)
      .sort((a, b) => b.guests - a.guests);
  }, [opData]);

  const totalGuests = storeStats.reduce((s, d) => s + d.guests, 0);
  const totalTx = storeStats.reduce((s, d) => s + d.txCount, 0);
  const totalSalesOp = storeStats.reduce((s, d) => s + d.sales, 0);

  return (
    <div className="chart-card" style={{ marginTop: 16 }}>
      <div className="chart-title">영업정보 매장별 집계</div>
      <table className="data-table">
        <thead>
          <tr><th>매장</th><th>총 고객수</th><th>영수건수</th><th>영수단가</th><th>객단가</th></tr>
        </thead>
        <tbody>
          {storeStats.map((s) => (
            <tr key={s.store}>
              <td className="td-store">{s.store}</td>
              <td className="td-num">{formatKRW(s.guests)}명</td>
              <td className="td-num">{formatKRW(s.txCount)}건</td>
              <td className="td-num">{s.txCount > 0 ? formatKRW(Math.round(s.sales / s.txCount)) : '-'}원</td>
              <td className="td-num">{s.guests > 0 ? formatKRW(Math.round(s.sales / s.guests)) : '-'}원</td>
            </tr>
          ))}
          <tr className="total-row">
            <td>합계</td>
            <td className="td-num">{formatKRW(totalGuests)}명</td>
            <td className="td-num">{formatKRW(totalTx)}건</td>
            <td className="td-num">{totalTx > 0 ? formatKRW(Math.round(totalSalesOp / totalTx)) : '-'}원</td>
            <td className="td-num">{totalGuests > 0 ? formatKRW(Math.round(totalSalesOp / totalGuests)) : '-'}원</td>
          </tr>
        </tbody>
      </table>
    </div>
  );
}

// ─── KPI 카드 ─────────────────────────────────────────────
function KpiCard({ label, value, sub, color, badge }) {
  return (
    <div className="kpi-card" style={{ borderTopColor: color }}>
      <div className="kpi-label">{label}</div>
      <div className="kpi-value" style={{ color, fontSize: badge ? 18 : undefined }}>{value}</div>
      <div className="kpi-sub">{sub}</div>
    </div>
  );
}
