/**
 * localStorage 기반 데이터 영속성 유틸리티
 * Firebase 없이 브라우저 로컬 저장소에 데이터를 보관합니다.
 */

const SALES_KEY = 'brand_sales_data';
const OP_KEY    = 'brand_op_data';

function safeGet(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function safeSet(key, data) {
  try {
    localStorage.setItem(key, JSON.stringify(data));
    return true;
  } catch (err) {
    console.warn('localStorage 저장 실패:', err);
    return false;
  }
}

// ─── 이지포스 판매 데이터 ───────────────────────────────

export async function saveAllData(allData) {
  return safeSet(SALES_KEY, allData);
}

export async function loadAllData() {
  return safeGet(SALES_KEY);
}

export async function clearAllData() {
  try {
    localStorage.removeItem(SALES_KEY);
    return true;
  } catch {
    return false;
  }
}

// ─── 영업정보 데이터 ────────────────────────────────────

export async function saveOpData(opData) {
  return safeSet(OP_KEY, opData);
}

export async function loadOpData() {
  return safeGet(OP_KEY);
}

export async function clearOpData() {
  try {
    localStorage.removeItem(OP_KEY);
    return true;
  } catch {
    return false;
  }
}
